SELECT analytics_order_facts.region, SUM(analytics_order_facts.gross_revenue) AS gross_revenue FROM analytics_order_facts WHERE analytics_order_facts.year = 2022 AND analytics_order_facts.month = 12 AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.customer_segment = 'public' AND analytics_order_facts.payment_method = 'debit' GROUP BY analytics_order_facts.region ORDER BY gross_revenue DESC, analytics_order_facts.region ASC LIMIT 12
